pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether via owner
        vm.deal(address(this), 1 ether);
        vm.prank(c.owner());
        (bool success,) = address(c).call{value: 1 ether}("");
        assertTrue(success);

        uint256 initialBalance = address(c).balance;
        // Non-owner calls sendMoney — in reference C, it fails silently (onlyOwner check), in buggy M it reverts
        address nonOwner = address(0x1234);
        vm.prank(nonOwner);
        (bool sendOk,) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", nonOwner, 0));

        // Now owner calls withdrawAll — reference succeeds and sends all balance to owner, buggy reverts
        vm.prank(c.owner());
        (bool withdrawOk,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // The key difference: after sequence, contract balance is 0 in reference, stays initial in buggy
        if (sendOk) {
            // Reference behavior: sendMoney reverted (onlyOwner), then withdrawAll succeeded, balance = 0
            assertTrue(withdrawOk);
            assertEq(address(c).balance, 0);
        } else {
            // Buggy behavior: sendMoney reverted, withdrawAll reverted, balance unchanged
            assertTrue(!withdrawOk);
            assertEq(address(c).balance, initialBalance);
        }
    }
}

