pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a recipient that always fails (e.g., non-payable or revert)
        Reverter reverter = new Reverter();
        address target = address(reverter);
        uint value = 1 ether;

        // Fund the contract with enough ether so call can attempt to send
        vm.deal(address(this), value);
        vm.prank(address(this)); // owner is msg.sender of deployment, which is this contract
        // Actually owner is address(this) because msg.sender in constructor is test contract
        // So we need to fund c and then call sendMoney as owner
        vm.deal(address(c), value);

        uint countBefore = c.depositsCount();

        // This call should revert in reference (P) because reverter.call will revert
        // In mutant (M), it does not revert
        bool ok;
        try c.sendMoney(target, value) {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference P: call reverts => ok == false, depositsCount unchanged
        // In mutant M: call succeeds => ok == true, depositsCount incremented
        // Assert that the test contract's behavior matches the reference: revert happened
        assertTrue(ok == false, "sendMoney should revert on failed call");
        assertTrue(c.depositsCount() == countBefore, "depositsCount unchanged if revert");
    }
}

contract Reverter {
    fallback() external payable {
        revert("fail");
    }
}

