pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: owner deposits 1 ether
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "deposit failed");

        // Non-owner tries to send 0.5 ether from contract to some address
        address nonOwner = address(0x123);
        address target = address(0x456);

        // Prank as non-owner
        vm.prank(nonOwner);

        // Call sendMoney — reference reverts (onlyOwner), buggy succeeds
        bool ok;
        try c.sendMoney(target, 0.5 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: the reference would revert (ok == false), buggy would succeed (ok == true)
        assertTrue(ok == false, "Reference contract should have reverted");
    }
}
